package main

import (
	"context"
	"fmt"
	"log"
	"os"

	"github.com/urfave/cli/v3"
)

func main() {
	cmd := &cli.Command{
		Name: "test-url",
		Flags: []cli.Flag{
			&cli.URLFlag{Name: "url", Usage: "URL to connect to"},
		},
		Action: func(ctx context.Context, c *cli.Command) error {
			url := c.URL("url")
			if url != nil {
				fmt.Printf("URL: %s\n", url.String())
				fmt.Printf("Scheme: %s\n", url.Scheme)
				fmt.Printf("Host: %s\n", url.Host)
			}
			return nil
		},
	}

	if err := cmd.Run(context.Background(), os.Args); err != nil {
		log.Fatal(err)
	}
}
EOF
