go run -run '' <<'EOF'
package main

import (
	"context"
	"fmt"
	"os"

	"github.com/urfave/cli/v3"
)

func main() {
	cmd := &cli.Command{
		Flags: []cli.Flag{
			&cli.RegexpFlag{
				Name:  "pattern",
				Usage: "regular expression pattern",
			},
		},
		Action: func(ctx context.Context, cmd *cli.Command) error {
			pattern := cmd.Regexp("pattern")
			if pattern != nil {
				fmt.Printf("Pattern: %s\n", pattern.String())
				fmt.Printf("Matches 'aaa': %v\n", pattern.MatchString("aaa"))
				fmt.Printf("Matches 'b': %v\n", pattern.MatchString("b"))
			}
			return nil
		},
	}

	if err := cmd.Run(context.Background(), os.Args); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
}
EOF
